<?php
session_start();
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../config/order_notifications.php';
if(empty($_SESSION['user_id'])){header('Location:login.php');exit;}
$userId=(int)$_SESSION['user_id'];$role=$_SESSION['role']??'';
if(!in_array($role,['publisher_admin','shop_admin'],true)){header('Location:home.php');exit;}
$sellerType=$role==='publisher_admin'?'publisher':'shop';
if($sellerType==='publisher')$q=$pdo->prepare('SELECT p.publisher_id id,p.company_name name FROM publisher_staff ps JOIN publishers p ON p.publisher_id=ps.publisher_id WHERE ps.user_id=? LIMIT 1');
else $q=$pdo->prepare('SELECT s.shop_id id,s.shop_name name FROM shop_staff ss JOIN shops s ON s.shop_id=ss.shop_id WHERE ss.user_id=? LIMIT 1');
$q->execute([$userId]);$seller=$q->fetch(PDO::FETCH_ASSOC);
if(!$seller){header('Location:dashboard.php');exit;}
$sellerId=(int)$seller['id'];$seller_name=$seller['name'];$active_menu='orders';
if(empty($_SESSION['admin_order_csrf']))$_SESSION['admin_order_csrf']=bin2hex(random_bytes(24));
$success='';$error='';
function ownAdminOrder(PDO $pdo,int $id,string $type,int $seller):?array{$q=$pdo->prepare('SELECT o.* FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE o.order_id=? AND b.seller_type=? AND b.seller_id=? LIMIT 1');$q->execute([$id,$type,$seller]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
function notifyOrderBuyer(PDO $pdo,array $o,string $title,string $body):void{wanawanNotifyOrderBuyer($pdo,$o,$title,$body);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['admin_order_csrf'],(string)($_POST['csrf_token']??'')))$error='คำขอหมดอายุ กรุณาลองใหม่';
 else{$id=(int)($_POST['order_id']??0);$order=ownAdminOrder($pdo,$id,$sellerType,$sellerId);
  if(!$order)$error='ไม่พบคำสั่งซื้อของร้าน';
  elseif(isset($_POST['save_tracking'])){$courier=trim($_POST['courier']??'');$tracking=trim($_POST['tracking_number']??'');if($order['payment_status']!=='paid'||$courier===''||$tracking==='')$error='กรุณายืนยันสลิปและกรอกข้อมูลจัดส่งให้ครบ';else{$pdo->beginTransaction();try{$pdo->prepare("UPDATE orders SET shipping_status='shipped',shipping_courier=?,tracking_number=?,shipped_at=NOW() WHERE order_id=?")->execute([$courier,$tracking,$id]);notifyOrderBuyer($pdo,$order,'คำสั่งซื้อกำลังจัดส่ง','จัดส่งผ่าน '.$courier.' เลขพัสดุ '.$tracking);$pdo->commit();$success='บันทึกเลขพัสดุและแจ้งผู้ซื้อแล้ว';}catch(Throwable $e){$pdo->rollBack();$error='บันทึกเลขพัสดุไม่สำเร็จ';}}}
  elseif(isset($_POST['complete_order'])){$pdo->prepare("UPDATE orders SET shipping_status='delivered' WHERE order_id=?")->execute([$id]);notifyOrderBuyer($pdo,$order,'คำสั่งซื้อสำเร็จแล้ว','ร้านอัปเดตว่าจัดส่งสำเร็จแล้ว');$success='ปิดคำสั่งซื้อเรียบร้อย';}
 }}
$status=$_GET['status']??'all';$search=ltrim(trim($_GET['search']??''),'#');$where='b.seller_type=:type AND b.seller_id=:seller';
$params=['type'=>$sellerType,'seller'=>$sellerId];
if($status==='packing')$where.=" AND o.payment_status='paid' AND o.shipping_status IN('pending','packing')";elseif($status==='shipped')$where.=" AND o.shipping_status='shipped'";elseif($status==='done')$where.=" AND o.shipping_status='delivered'";
if($search!==''){$where.=" AND o.order_number LIKE :search";$params['search']="%{$search}%";}
$q=$pdo->prepare("SELECT DISTINCT o.* FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE $where ORDER BY o.created_at DESC");$q->execute($params);$orders=$q->fetchAll(PDO::FETCH_ASSOC);
$iq=$pdo->prepare('SELECT oi.*,b.title,b.author,b.image_cover FROM order_items oi JOIN books b ON b.book_id=oi.book_id WHERE oi.order_id=? AND b.seller_type=? AND b.seller_id=?');
foreach($orders as &$o){$iq->execute([$o['order_id'],$sellerType,$sellerId]);$o['items']=$iq->fetchAll(PDO::FETCH_ASSOC);}unset($o);
$s=$pdo->prepare("SELECT COUNT(DISTINCT o.order_id) total,COUNT(DISTINCT CASE WHEN o.payment_status='paid' AND o.shipping_status IN('pending','packing') THEN o.order_id END) packing FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE b.seller_type=? AND b.seller_id=?");$s->execute([$sellerType,$sellerId]);$stats=$s->fetch(PDO::FETCH_ASSOC);
function adminBookImg(?string $v):string{
 if(!$v)return '/assets/image/minilogo.png';
 $v=str_replace('\\','/',trim($v));
 if(preg_match('#^https?://#i',$v))return $v;
 $v=ltrim($v,'/');
 if(str_starts_with($v,'pages/uploads/'))return '/'.$v;
 if(str_starts_with($v,'uploads/')){
  // New book uploads live at the project root. Keep supporting older files
  // that were stored under pages/uploads before the upload path was changed.
  if(is_file(__DIR__.'/../'.$v))return '/'.$v;
  if(is_file(__DIR__.'/'.$v))return '/pages/'.$v;
  return '/'.$v;
 }
 if(str_starts_with($v,'assets/'))return '/'.$v;
 return '/assets/image/books/'.$v;
}
function adminSlip(?string $v):string{return $v?'/pages/'.ltrim(str_replace('\\','/',$v),'/'):'';}
function adminState(array $o):array{if($o['shipping_status']==='cancelled'||$o['payment_status']==='cancelled')return['ยกเลิกแล้ว','cancel'];if($o['shipping_status']==='delivered')return['สำเร็จแล้ว','done'];if($o['shipping_status']==='shipped')return['กำลังจัดส่ง','ship'];if($o['payment_status']==='paid')return['รอจัดส่ง','paid'];if(strtotime($o['created_at'])<time()-86400)return['ยกเลิกแล้ว','cancel'];return['รอชำระเงิน','wait'];}
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ติดตามคำสั่งซื้อ - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>
*{box-sizing:border-box;margin:0;padding:0}body{font-family:var(--font-family);background:#fff;color:var(--text-dark);display:flex;min-height:100vh}.sidebar{width:260px;min-height:100vh;background:#f9e1eb;display:flex;flex-direction:column;padding:25px 16px;position:fixed}.sidebar-logo{display:flex;align-items:center;gap:10px;padding:0 12px 30px}.sidebar-logo img{width:74px}.sidebar-logo-text{font-size:24px;color:var(--secondary-color);font-weight:700}.sidebar-logo-sub,.profile-role{font-size:11px;color:var(--primary-color)}.sidebar-nav{display:flex;flex-direction:column;gap:9px;flex:1}.nav-item{display:flex;align-items:center;gap:12px;padding:13px 15px;border-radius:8px;text-decoration:none;color:#91576d}.nav-item svg{width:20px;height:20px}.nav-item.active,.nav-item:hover{background:#d18aa7;color:#fff}.admin-order-badge{margin-left:auto;background:#c83232;color:#fff;border-radius:20px;min-width:23px;padding:3px 7px;text-align:center}.sidebar-profile{display:flex;gap:10px;align-items:center;padding:15px}.profile-avatar{width:40px;height:40px;border-radius:50%;background:#fff;display:grid;place-items:center;overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-seller,.profile-name{font-size:12px;font-weight:700}.main{margin-left:260px;padding:55px 38px;width:calc(100% - 260px)}.head{display:flex;justify-content:space-between;align-items:center}.head h1{color:var(--secondary-color);font-size:30px}.bell{text-decoration:none;color:#c77c99;font-size:25px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:28px 0}.stat{border:1px solid #dfbdc8;border-radius:14px;padding:25px}.stat strong{display:block;color:#d88fac;font-size:28px}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:18px;border:1px solid #e3c3ce;border-bottom:0;border-radius:14px 14px 0 0}.filters a{display:inline-block;padding:8px 13px;text-decoration:none;color:#765d66;border-radius:18px}.filters a.active{background:#d18aa7;color:#fff}.tablebox{overflow:auto;border:1px solid #e3c3ce;border-radius:0 0 14px 14px}.orders{width:100%;border-collapse:collapse;min-width:900px}.orders th,.orders td{padding:15px;border-bottom:1px solid #ead6dd;text-align:left}.book{display:flex;align-items:center;gap:10px}.book img{width:45px;height:62px;object-fit:cover;border-radius:5px}.badge{padding:6px 12px;border-radius:18px;background:#f7d6df;color:#c54848;font-weight:700;font-size:12px}.btn{border:0;border-radius:8px;padding:9px 13px;background:var(--secondary-color);color:#fff;cursor:pointer}.notice{padding:12px 16px;border-radius:8px;margin:15px 0}.ok{background:#e9f5e5;color:#39703a}.bad{background:#fde5e1;color:#a33}.modal{position:fixed;inset:0;background:#0006;display:none;align-items:center;justify-content:center;padding:20px;z-index:500}.modal.open{display:flex}.modalbox{background:#fff;border-radius:16px;padding:28px;width:min(600px,100%);max-height:90vh;overflow:auto}.grid{display:grid;grid-template-columns:repeat(2, 1fr) 320px;gap:24px}.slip{width:100%;max-height:430px;object-fit:contain;background:#f7f3f4}.field{margin:12px 0}.field input{width:100%;padding:11px;border:1px solid #ccc;border-radius:7px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}@media(max-width:800px){.sidebar{position:static;width:100%}.main{margin:0;width:100%;padding:25px 14px}.stats{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2, 1fr)}body{display:block}}
</style></head><body><?php include __DIR__.'/../components/sidebar.php';?><main class="main"><div class="head"><h1>การติดตามคำสั่งซื้อ</h1><a class="bell" href="notifications.php" title="การแจ้งเตือน">🔔</a></div><div class="stats"><div class="stat">รายการคำสั่งซื้อทั้งหมด<strong><?=$stats['total']??0?></strong></div><div class="stat">รอดำเนินการจัดส่ง<strong><?=$stats['packing']??0?></strong></div></div><?php if($success):?><div class="notice ok"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><div class="toolbar"><h3>รายการธุรกรรมและการจัดส่งล่าสุด</h3><div style="display:flex;gap:15px;align-items:center;flex-wrap:wrap"><form method="get" style="display:flex;gap:8px;align-items:center;"><?php if($status!=='all'):?><input type="hidden" name="status" value="<?=htmlspecialchars($status)?>"><?php endif;?><input type="text" name="search" value="<?=htmlspecialchars($search)?>" placeholder="ค้นหาเลขคำสั่งซื้อ..." style="padding:8px 12px;border:1px solid #d8c9c4;border-radius:8px;outline:none;font-size:13px;width:240px"><button type="submit" class="btn" style="padding:8px 15px;min-height:0">ค้นหา</button><a href="?status=<?=htmlspecialchars($status)?>" class="btn" style="padding:8px 15px;min-height:0;background:#f3f4f6;color:#555;text-decoration:none;border:1px solid #ddd;font-weight:normal;">ล้าง</a></form><nav class="filters"><?php foreach(['all'=>'ทั้งหมด','packing'=>'รอจัดส่ง','shipped'=>'กำลังจัดส่ง','done'=>'สำเร็จ'] as $k=>$v):?><a class="<?=$status===$k?'active':''?>" href="?status=<?=$k?><?=($search!==''?'&search='.urlencode($search):'')?>"><?=$v?></a><?php endforeach;?></nav></div></div><div class="tablebox"><table class="orders"><thead><tr><th>รหัสคำสั่งซื้อ</th><th>รายการหนังสือ</th><th>ผู้รับ</th><th>หมายเลขติดตาม</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="6" style="text-align:center;padding:70px">ยังไม่มีคำสั่งซื้อในหมวดนี้</td></tr><?php else:foreach($orders as $o):$first=$o['items'][0]??[];[$statusText, $statusClass]=adminState($o);?><tr><td>#<?=htmlspecialchars($o['order_number'])?></td><td><div class="book"><img src="<?=htmlspecialchars(adminBookImg($first['image_cover']??null))?>"><div><strong><?=htmlspecialchars($first['title']??'-')?></strong><br><small><?=count($o['items'])?> รายการ</small></div></div></td><td><strong><?=htmlspecialchars($o['shipping_name'])?></strong><br><small><?=htmlspecialchars($o['shipping_phone'])?></small></td><td><?=htmlspecialchars($o['tracking_number']?:'-')?></td><td><span class="badge badge-<?=$statusClass?>"><?=$statusText?></span></td><td><button class="btn detail" data-order='<?=htmlspecialchars(json_encode(['order'=>$o,'slip'=>adminSlip($o['payment_slip_url']??null)],JSON_UNESCAPED_UNICODE),ENT_QUOTES)?>'>ดูรายละเอียด</button></td></tr><?php endforeach;endif;?></tbody></table></div></main>
<div class="modal" id="modal"><div class="modalbox"><h2 id="mNumber"></h2><div class="grid" style="grid-template-columns: 1fr;"><section><div style="font-size: 13px; color: #777; margin-bottom: 15px;">สั่งซื้อเมื่อ: <span id="mDate"></span><br>ชำระเงินเมื่อ: <span id="mPaidDate"></span></div><div id="mItems"></div><hr><div style="background:#f9f9f9; padding: 15px; border-radius: 8px; margin-bottom: 15px; font-size: 14px;"><div style="display:flex; justify-content:space-between; margin-bottom:8px"><span>รวมค่าสินค้า</span><strong id="mSubtotal"></strong></div><div style="display:flex; justify-content:space-between; margin-bottom:8px"><span>ส่วนลดร้านค้า <span id="mPromoName" style="font-size:11px; font-weight:normal;"></span></span><strong id="mDiscount" style="color: #2e7d32;"></strong></div><div style="display:flex; justify-content:space-between; margin-bottom:8px"><span>ค่าจัดส่ง</span><strong id="mShippingFee"></strong></div><div style="display:flex; justify-content:space-between; margin-bottom:12px; padding-bottom: 8px; border-bottom: 1px dashed #ccc;"><span>หักค่าธรรมเนียมการขาย (GP)</span><strong id="mGP" style="color:#bc443d"></strong></div><div style="display:flex; justify-content:space-between; font-size: 16px;"><strong>รายได้สุทธิที่จะได้รับ</strong><strong id="mNet" style="color:#d35400"></strong></div></div><p id="mBuyer"></p><p id="mAddress"></p><div id="mActions" class="actions"></div></section></div><button class="btn" id="close" style="width:100%; margin-top:15px; background:#fff; color:#91576d; border:1px solid #e3c3ce;">ปิดหน้าต่าง</button></div></div><script>
const token=<?=json_encode($_SESSION['admin_order_csrf'])?>,modal=document.getElementById('modal');const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));function form(id,name,label,extra=''){return `<form method="post"><input type="hidden" name="csrf_token" value="${token}"><input type="hidden" name="order_id" value="${id}">${extra}<button class="btn" name="${name}">${label}</button></form>`}
document.querySelectorAll('.detail').forEach(b=>b.onclick=()=>{const d=JSON.parse(b.dataset.order),o=d.order;document.getElementById('mNumber').textContent='#'+o.order_number;document.getElementById('mDate').textContent=o.created_at||'-';document.getElementById('mPaidDate').textContent=o.paid_at||(o.payment_status==='paid'?'(ชำระแล้ว แต่ไม่ระบุเวลา)':'ยังไม่ชำระเงิน');document.getElementById('mItems').innerHTML=o.items.map(i=>`<p><strong>${esc(i.title)}</strong> × ${i.quantity} — ฿${Number(i.price_at_purchase*i.quantity).toLocaleString(undefined,{minimumFractionDigits:2})}</p>`).join('');const orderTime=new Date(o.created_at).getTime();const isExpired=(!o.paid_at&&o.payment_status==='pending'&&(Date.now()-orderTime)>86400000);const isCancelled=(o.payment_status==='cancelled'||['cancelled','returned'].includes(o.shipping_status)||isExpired);const rawSubtotal=o.items.reduce((sum,i)=>sum+(i.price_at_purchase*i.quantity),0);const subtotal=isCancelled?0:rawSubtotal;const discount=isCancelled?0:Number(o.discount_amount||0);const shippingFee=isCancelled?0:Number(o.shipping_fee||0);const gp=isCancelled?0:(Number(o.gp_amount||0)>0?Number(o.gp_amount):(subtotal*0.10));const net=isCancelled?0:(Number(o.net_payout||0)>0?Number(o.net_payout):(subtotal-gp-discount+shippingFee));document.getElementById('mSubtotal').textContent='฿'+subtotal.toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById('mPromoName').textContent=o.promotion_name?'('+o.promotion_name+')':'';document.getElementById('mDiscount').textContent='-฿'+discount.toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById('mShippingFee').textContent='฿'+shippingFee.toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById('mGP').textContent='-฿'+gp.toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById('mNet').textContent='฿'+net.toLocaleString(undefined,{minimumFractionDigits:2});if(isCancelled){document.getElementById('mBuyer').textContent='คำสั่งซื้อถูกยกเลิก';document.getElementById('mAddress').textContent=isExpired?'(ไม่ได้ชำระเงินภายใน 24 ชั่วโมง)':'';}else if(o.payment_status==='paid' || ['shipped','delivered'].includes(o.shipping_status)){document.getElementById('mBuyer').textContent='ผู้รับ: '+o.shipping_name+' · '+o.shipping_phone;document.getElementById('mAddress').textContent=o.shipping_address;}else{document.getElementById('mBuyer').textContent='รอแอดมินตรวจสอบการชำระเงิน';document.getElementById('mAddress').textContent='(ที่อยู่จัดส่งจะแสดงหลังจากแอดมินอนุมัติสลิปแล้ว)';}let a='';if(o.payment_status==='paid'&&!['shipped','delivered'].includes(o.shipping_status)&&!isCancelled)a+=form(o.order_id,'save_tracking','บันทึกการจัดส่ง','<div class="field"><input name="courier" required placeholder="บริษัทขนส่ง"></div><div class="field"><input name="tracking_number" required placeholder="เลขพัสดุ"></div>');if(o.shipping_status==='shipped')a+=form(o.order_id,'complete_order','จัดส่งสำเร็จ');document.getElementById('mActions').innerHTML=a;modal.classList.add('open')});document.getElementById('close').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};
document.querySelectorAll('a.bell').forEach(link=>link.remove());
const courierOptions=['ไปรษณีย์ไทย','Flash Express','Kerry Express','J&T Express','SPX Express','Ninja Van','DHL Express','BEST Express'];
const actionObserver=new MutationObserver(()=>{const old=document.querySelector('#mActions input[name="courier"]');if(!old)return;const select=document.createElement('select');select.name='courier';select.required=true;select.className='courier-select';select.innerHTML='<option value="">เลือกบริษัทขนส่ง</option>'+courierOptions.map(v=>`<option value="${v}">${v}</option>`).join('')+'<option value="other">อื่น ๆ / กรอกเอง</option>';const custom=document.createElement('input');custom.type='text';custom.placeholder='กรอกชื่อบริษัทขนส่ง';custom.className='custom-courier';custom.hidden=true;select.addEventListener('change',()=>{custom.hidden=select.value!=='other';if(select.value==='other'){select.removeAttribute('name');custom.name='courier';custom.required=true;custom.focus()}else{select.name='courier';custom.removeAttribute('name');custom.required=false}});old.replaceWith(select);select.insertAdjacentElement('afterend',custom)});
actionObserver.observe(document.getElementById('mActions'),{childList:true,subtree:true});
</script>
