#mNoSlip{text-align:center!important;padding:75px 15px!important;color:#9a8b90!important;background:#f8f4f2!important;border:1px dashed #d7b8c3!important;border-radius:12px!important}
#mActions{display:grid!important;grid-template-columns:1fr!important;gap:12px!important;margin-top:22px!important}
#mActions form{display:grid!important;grid-template-columns:1fr 1fr!important;gap:11px!important;padding:18px!important;background:#fff!important;border:1px solid #ead6dd!important;border-radius:12px!important}
#mActions .field{margin:0!important}
#mActions .field:first-of-type{grid-column:1}
#mActions .field:nth-of-type(2){grid-column:2}
#mActions form>.btn{grid-column:1/-1!important}
.courier-select,.custom-courier,#mActions input{width:100%!important;min-height:44px!important;padding:10px 12px!important;border:1px solid #d8c9c4!important;border-radius:9px!important;background:#fff!important;color:#54484b!important;font-size:14px!important;outline:none!important}
.courier-select:focus,.custom-courier:focus,#mActions input:focus{border-color:#d18aa7!important;box-shadow:0 0 0 3px rgba(209,138,167,.15)!important}
.modalbox>.btn#close{margin:0 30px 26px!important;width:calc(100% - 60px)!important;background:#fff!important;color:var(--secondary-color)!important;border:1px solid #e8cbd5!important;border-radius:8px!important}
.modalbox .btn{min-height:42px!important;font-size:14px!important;font-weight:600!important}
@media(max-width:760px){.modal{padding:12px!important}.modalbox>.grid{grid-template-columns:1fr!important}.modalbox>.grid>section+section{border-left:0!important;border-top:1px solid #ead6dd!important}#mActions form{grid-template-columns:1fr!important}#mActions .field{grid-column:1!important}}
.orders{min-width:1060px!important}
.orders th:nth-child(6),.orders td:nth-child(6){min-width:145px!important;width:145px!important}
.orders th:nth-child(7),.orders td:nth-child(7){min-width:135px!important;width:135px!important}
.orders .badge{display:inline-flex!important;align-items:center!important;justify-content:center!important;min-height:31px!important;padding:6px 12px!important;white-space:nowrap!important;line-height:1.2!important}
.badge-cancel{background:#fde5e1!important;color:#c54848!important}
.badge-done{background:#e9f5e5!important;color:#39703a!important}
.badge-ship{background:#e3f2fd!important;color:#1976d2!important}
.badge-paid{background:#fff3e0!important;color:#e65100!important}
.badge-wait{background:#f3f4f6!important;color:#4b5563!important}
.orders td:nth-child(7) .btn{min-width:108px!important;white-space:nowrap!important}
</style>
<script>
const notificationOrderNumber=new URLSearchParams(location.search).get('order');
if(notificationOrderNumber){const notificationOrderButton=[...document.querySelectorAll('.detail')].find(button=>{try{return JSON.parse(button.dataset.order).order.order_number===notificationOrderNumber}catch(_){return false}});if(notificationOrderButton)notificationOrderButton.click();}
</script>
</body></html>
